def check(conf, token, prev, next, nextnext, context):
    if 'flow_nest_count' not in context:
        context['flow_nest_count'] = 0

    if isinstance(token, (yaml.FlowMappingStartToken,
                          yaml.FlowSequenceStartToken)):
        context['flow_nest_count'] += 1
    elif isinstance(token, (yaml.FlowMappingEndToken,
                            yaml.FlowSequenceEndToken)):
        context['flow_nest_count'] -= 1

    is_key = isinstance(token, yaml.tokens.ScalarToken) and isinstance(prev, yaml.KeyToken)
    is_value = isinstance(token, yaml.tokens.ScalarToken) and isinstance(prev, (
        yaml.BlockEntryToken, yaml.FlowEntryToken, yaml.FlowSequenceStartToken,
        yaml.TagToken, yaml.ValueToken))

    if not (is_key or is_value):
        return

    # For keys, we need to check if key checking is enabled
    if is_key and not conf['check-keys']:
        return

